'use strict';

const { csvError, DUPLICATE_HEADER, FIELD_COUNT_MISMATCH } = require('./errors');

/**
 * Header mode: takes the first record as column names and turns every later
 * record into an object keyed by them.
 */
class HeaderMapper {
  constructor() {
    /** @type {string[] | null} null until the header record has ended. */
    this.columns = null;
    this.seen = new Set();
  }

  /**
   * Called as each header field ends, so a duplicate is reported before any
   * error that appears later in the header record.
   */
  addName(name, line, column) {
    if (this.seen.has(name)) {
      throw csvError(DUPLICATE_HEADER, `Duplicate header name ${JSON.stringify(name)}`, line, column);
    }
    this.seen.add(name);
  }

  /**
   * Returns the record as an object, or null for the header record itself.
   * @param {string[]} fields
   * @param {number} line the line the record starts on
   */
  toRecord(fields, line) {
    const columns = this.columns;
    if (columns === null) {
      this.columns = fields;
      this.seen = null;
      return null;
    }
    if (fields.length !== columns.length) {
      throw csvError(
        FIELD_COUNT_MISMATCH,
        `Record has ${fields.length} field${fields.length === 1 ? '' : 's'} but the header has ${columns.length}`,
        line,
        1,
      );
    }
    const record = {};
    for (let i = 0; i < columns.length; i++) {
      const name = columns[i];
      if (name === '__proto__') {
        // Plain assignment would call the Object.prototype setter and drop the value.
        Object.defineProperty(record, name, {
          value: fields[i],
          enumerable: true,
          writable: true,
          configurable: true,
        });
      } else {
        record[name] = fields[i];
      }
    }
    return record;
  }
}

module.exports = { HeaderMapper };

