'use strict';

const { csvError, UNCLOSED_QUOTE, INVALID_CLOSING_QUOTE } = require('./errors');
const { HeaderMapper } = require('./header');

const QUOTE = 0x22;
const LF = 0x0a;
const CR = 0x0d;
const BOM = 0xfeff;

// Scanner states.
const LINE_START = 0; // nothing read since the last line break or the start of input
const FIELD_START = 1; // just after a delimiter
const UNQUOTED = 2;
const QUOTED = 3;
const QUOTE_IN_QUOTED = 4; // a `"` inside a quoted field: the closing quote or the first half of `""`

/**
 * Incremental CSV scanner shared by parse() and createParser().
 *
 * Every code unit is examined once. Between chunks the scanner keeps only
 * its state, the current record's fields, the current field's text and
 * position counters, so memory and time stay proportional to the input.
 * Records are collected as their line break is read and handed out by
 * write() and end().
 */
class Parser {
  /**
   * @param {{delimiter: string, header: boolean, skipEmptyLines: boolean}} options
   *   already validated by parseOptions()
   */
  constructor(options) {
    this.delimiter = options.delimiter.charCodeAt(0);
    this.skipEmptyLines = options.skipEmptyLines;
    this.header = options.header ? new HeaderMapper() : null;

    this.state = LINE_START;
    this.fields = [];
    // Text of the current field read in earlier chunks or before an escaped quote.
    this.parts = [];
    this.records = [];

    this.started = false; // the first code unit (a possible BOM) has been seen
    this.pendingCR = false; // the last chunk ended with a CR; a leading LF completes the CRLF

    this.offset = 0; // absolute offset of the current chunk's first code unit
    this.line = 1;
    this.lineStart = 0; // absolute offset of the current line's first code unit
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;
  }

  /**
   * Scans a chunk and returns the records it completed.
   * @param {string} chunk
   * @returns {Array<string[] | Record<string, string>>}
   */
  write(chunk) {
    const length = chunk.length;
    if (length === 0) return this.take();
    let start = 0;
    if (!this.started) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) {
        // Positions are reported as if the BOM were not there.
        start = 1;
        this.lineStart = 1;
      }
    }
    if (this.pendingCR) {
      this.pendingCR = false;
      if (chunk.charCodeAt(0) === LF) {
        // Skipped as a record terminator; inside a quoted field it stays in
        // the text because scan() slices from index 0.
        start = 1;
        this.lineStart = this.offset + 1;
      }
    }
    this.scan(chunk, start);
    this.offset += length;
    return this.take();
  }

  /**
   * Finishes the input and returns the last record, if any.
   * @returns {Array<string[] | Record<string, string>>}
   */
  end() {
    switch (this.state) {
      case FIELD_START:
        this.endField('');
        this.endRecord();
        break;
      case UNQUOTED:
      case QUOTE_IN_QUOTED:
        this.endField(this.fieldText(''));
        this.endRecord();
        break;
      case QUOTED:
        throw csvError(UNCLOSED_QUOTE, 'Quoted field is never closed', this.fieldLine, this.fieldColumn);
      default:
        // LINE_START: no input, or it ended with a line break, which does not
        // start another record.
        break;
    }
    this.state = LINE_START;
    return this.take();
  }

  scan(chunk, start) {
    const length = chunk.length;
    const delimiter = this.delimiter;
    let state = this.state;
    // Start of the current field's text that has not been copied out yet.
    let segment = 0;

    for (let i = start; i < length; i++) {
      const c = chunk.charCodeAt(i);

      if (state === QUOTED) {
        if (c === QUOTE) {
          if (i > segment) this.parts.push(chunk.slice(segment, i));
          state = QUOTE_IN_QUOTED;
        } else if (c === CR || c === LF) {
          i = this.lineBreak(chunk, i, c);
        }
        continue;
      }

      if (state === UNQUOTED) {
        if (c === delimiter) {
          this.endField(this.fieldText(chunk.slice(segment, i)));
          state = FIELD_START;
