'use strict';

const { CsvError } = require('./errors');
const { describe, parseOptions } = require('./options');
const { Parser } = require('./parser');
const { stringify } = require('./stringify');

/**
 * Parses CSV text into records.
 *
 * @param {string} text
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {Array<string[] | Record<string, string>>} arrays of fields, or
 *   objects keyed by the first record when `header` is true
 * @throws {TypeError} when `text` is not a string or an option is invalid
 * @throws {CsvError} when the input is malformed
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`text must be a string, received ${describe(text)}`);
  }
  const parser = new Parser(parseOptions(options));
  const records = parser.write(text);
  for (const record of parser.end()) records.push(record);
  return records;
}

/**
 * Creates a parser for input that arrives in pieces. Chunks may be split
 * anywhere; the records and errors are the same as parse() on the whole text.
 *
 * Once end() has been called, or either method has thrown, both methods
 * throw an Error.
 *
 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
 * @returns {{
 *   write(chunk: string): Array<string[] | Record<string, string>>,
 *   end(): Array<string[] | Record<string, string>>,
 * }}
 * @throws {TypeError} when an option is invalid
 */
function createParser(options = {}) {
  const parser = new Parser(parseOptions(options));
  let closedReason = null;

  function run(method, step) {
    if (closedReason !== null) {
      throw new Error(`Cannot call ${method}(): the parser ${closedReason}`);
    }
    try {
      return step();
    } catch (err) {
      closedReason = `failed with an earlier error (${err.message})`;
      throw err;
    }
  }

  return {
    write(chunk) {
      return run('write', () => {
        if (typeof chunk !== 'string') {
          throw new TypeError(`chunk must be a string, received ${describe(chunk)}`);
        }
        return parser.write(chunk);
      });
    },
    end() {
      return run('end', () => {
        const records = parser.end();
        closedReason = 'has already ended';
        return records;
      });
    },
  };
}

module.exports = { parse, createParser, stringify, CsvError };

