'use strict';

const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

/** Deterministic PRNG (mulberry32) so fuzz failures can be replayed from the seed. */
function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function errorSummary(err) {
  assert.ok(err instanceof CsvError, `expected a CsvError, got ${err && err.stack}`);
  return { error: { line: err.line, column: err.column, code: err.code, message: err.message } };
}

/** parse() result as `{records}` or `{error}` so success and failure compare alike. */
function parseOutcome(text, options) {
  try {
    return { records: parse(text, options) };
  } catch (err) {
    return errorSummary(err);
  }
}

/** Feeds chunks to a fresh createParser() and returns the same shape as parseOutcome. */
function streamOutcome(chunks, options) {
  const parser = createParser(options);
  const records = [];
  try {
    for (const chunk of chunks) {
      for (const record of parser.write(chunk)) records.push(record);
    }
    for (const record of parser.end()) records.push(record);
    return { records };
  } catch (err) {
    return errorSummary(err);
  }
}

/** Splits text at the given ascending indices. */
function splitAt(text, points) {
  const chunks = [];
  let from = 0;
  for (const point of points) {
    chunks.push(text.slice(from, point));
    from = point;
  }
  chunks.push(text.slice(from));
  return chunks;
}

/** Splits text into chunks of random length (including empty chunks). */
function randomChunks(text, rand, maxLength = 5) {
  const chunks = [];
  let from = 0;
  while (from < text.length) {
    const size = Math.floor(rand() * (maxLength + 1));
    chunks.push(text.slice(from, from + size));
    from += size;
  }
  return chunks;
}

module.exports = { random, parseOutcome, streamOutcome, splitAt, randomChunks };

