'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse } = require('../src/csv');

function cases(table, options) {
  for (const [name, input, expected] of table) {
    it(name, () => assert.deepStrictEqual(parse(input, options), expected));
  }
}

describe('parse: fields', () => {
  cases([
    ['returns [] for an empty string', '', []],
    ['parses a single field', 'a', [['a']]],
    ['splits fields on commas', 'a,b,c', [['a', 'b', 'c']]],
    ['keeps empty fields at the start, middle and end', ',a,,', [['', 'a', '', '']]],
    ['reads a lone delimiter as two empty fields', ',', [['', '']]],
    ['returns numbers and booleans as strings', '1,2.5,true', [['1', '2.5', 'true']]],
    ['keeps non-ASCII text', 'é,日本,😀', [['é', '日本', '😀']]],
  ]);
});

describe('parse: line breaks', () => {
  cases([
    ['separates records with LF', 'a\nb', [['a'], ['b']]],
    ['separates records with CRLF', 'a\r\nb', [['a'], ['b']]],
    ['separates records with CR', 'a\rb', [['a'], ['b']]],
    ['accepts mixed line breaks in one input', 'a\nb\r\nc\rd', [['a'], ['b'], ['c'], ['d']]],
    ['treats LF followed by CR as two line breaks', 'a\n\rb', [['a'], [''], ['b']]],
    ['ignores one trailing LF', 'a,b\n', [['a', 'b']]],
    ['ignores one trailing CRLF', 'a\r\n', [['a']]],
    ['ignores one trailing CR', 'a\r', [['a']]],
    ['keeps an empty line before the final line break', 'a\n\n', [['a'], ['']]],
    ['reads a lone line break as one empty record', '\n', [['']]],
    ['reads a lone CRLF as one empty record', '\r\n', [['']]],
    ['reads two CRLFs as two empty records', '\r\n\r\n', [[''], ['']]],
    ['keeps empty lines in the middle', 'a\n\nb', [['a'], [''], ['b']]],
    ['keeps a leading empty line', '\na', [[''], ['a']]],
    ['ends a record with an empty field after a trailing delimiter', 'a,\nb', [['a', ''], ['b']]],
  ]);
});

describe('parse: skipEmptyLines', () => {
  const skip = { skipEmptyLines: true };
  cases(
    [
      ['skips empty lines anywhere', '\na\n\nb\n\n', [['a'], ['b']]],
      ['returns [] when every line is empty', '\n\r\n\r', []],
      ['does not skip a line holding a quoted empty field', '""\n\n', [['']]],
      ['does not skip a line holding only whitespace', ' \n', [[' ']]],
      ['does not skip a line holding only a delimiter', ',\n', [['', '']]],
    ],
    skip,
  );

  it('keeps empty lines when skipEmptyLines is false', () => {
