  fieldText(tail) {
    const parts = this.parts;
    if (parts.length === 0) return tail;
    if (tail !== '') parts.push(tail);
    const text = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return text;
  }

  endField(value) {
    if (this.header !== null && this.header.columns === null) {
      this.header.addName(value, this.fieldLine, this.fieldColumn);
    }
    this.fields.push(value);
  }

  endRecord() {
    const fields = this.fields;
    this.fields = [];
    if (this.header === null) {
      this.records.push(fields);
      return;
    }
    const record = this.header.toRecord(fields, this.recordLine);
    if (record !== null) this.records.push(record);
  }

  take() {
    const records = this.records;
    this.records = [];
    return records;
  }
}

module.exports = { Parser };

