'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { createParser, CsvError } = require('../src/csv');
const { random, parseOutcome, streamOutcome, splitAt, randomChunks } = require('./helpers');

describe('createParser: record timing', () => {
  it('returns each record from the write whose chunk holds its line break', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write('a,b\nc'), [['a', 'b']]);
    assert.deepStrictEqual(parser.write(',d\ne,f\n'), [['c', 'd'], ['e', 'f']]);
    assert.deepStrictEqual(parser.end(), []);
  });

  it('returns [] from a write that completes no record', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write('abc'), []);
    assert.deepStrictEqual(parser.write(',def'), []);
    assert.deepStrictEqual(parser.end(), [['abc', 'def']]);
  });

  it('accepts empty chunks anywhere', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write(''), []);
    assert.deepStrictEqual(parser.write('a\n'), [['a']]);
    assert.deepStrictEqual(parser.write(''), []);
    assert.deepStrictEqual(parser.end(), []);
  });

  it('returns [] from end() when nothing was written', () => {
    assert.deepStrictEqual(createParser().end(), []);
  });

  it('returns a record ended by CR at once and reads the next LF as part of that CRLF', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write('a\r'), [['a']]);
    assert.deepStrictEqual(parser.write('\nb'), []);
    assert.deepStrictEqual(parser.end(), [['b']]);
  });

  it('reads a CR at a chunk end followed by another CR as two line breaks', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write('a\r'), [['a']]);
    assert.deepStrictEqual(parser.write('\rb'), [['']]);
    assert.deepStrictEqual(parser.end(), [['b']]);
  });

  it('keeps a CRLF split inside a quoted field as text', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write('"a\r'), []);
    assert.deepStrictEqual(parser.write('\nb"\n'), [['a\r\nb']]);
  });

  it('joins an escaped quote split between chunks', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write('"a"'), []);
    assert.deepStrictEqual(parser.write('"b"\n'), [['a"b']]);
  });

  it('returns a quoted record when the chunk after the closing quote has the line break', () => {
    const parser = createParser();
    assert.deepStrictEqual(parser.write('"a"'), []);
    assert.deepStrictEqual(parser.write('\n'), [['a']]);
  });

  it('drops a BOM at the start of the first non-empty chunk only', () => {
    const first = createParser();
    first.write('');
    assert.deepStrictEqual(first.write('﻿a\n'), [['a']]);

    const later = createParser();
    later.write('a');
    assert.deepStrictEqual(later.write('﻿b\n'), [['a﻿b']]);
  });

  it('returns objects and never the header record in header mode', () => {
    const parser = createParser({ header: true });
    assert.deepStrictEqual(parser.write('id,name\n'), []);
    assert.deepStrictEqual(parser.write('1,ann\n2,'), [{ id: '1', name: 'ann' }]);
    assert.deepStrictEqual(parser.end(), [{ id: '2', name: '' }]);
  });

  it('applies delimiter and skipEmptyLines options', () => {
    const parser = createParser({ delimiter: ';', skipEmptyLines: true });
    assert.deepStrictEqual(parser.write('a;b\n\n'), [['a', 'b']]);
    assert.deepStrictEqual(parser.end(), []);
  });

  it('keeps separate state for parsers used at the same time', () => {
    const left = createParser();
    const right = createParser({ delimiter: ';' });
    const out = { left: [], right: [] };
    const leftChunks = ['"x', ',y"', ',1\n', '2'];
    const rightChunks = ['a;', 'b\r', '\n"', 'c"'];
    for (let i = 0; i < 4; i++) {
      out.left.push(...left.write(leftChunks[i]));
      out.right.push(...right.write(rightChunks[i]));
    }
    out.left.push(...left.end());
    out.right.push(...right.end());
    assert.deepStrictEqual(out, { left: [['x,y', '1'], ['2']], right: [['a', 'b'], ['c']] });
  });
});

describe('createParser: lifecycle and errors', () => {
  it('rejects non-string chunks with a TypeError', () => {
    for (const chunk of [undefined, null, 1, Buffer.from('a'), ['a'], {}]) {
      assert.throws(() => createParser().write(chunk), TypeError);
    }
  });

  it('validates options when the parser is created', () => {
    assert.throws(() => createParser({ delimiter: '"' }), TypeError);
    assert.throws(() => createParser(null), TypeError);
    assert.throws(() => createParser({ header: 'yes' }), TypeError);
  });

  it('throws an Error from write and end after end()', () => {
    const parser = createParser();
    parser.end();
    assert.throws(() => parser.write('a'), { name: 'Error', message: /has already ended/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /has already ended/ });
  });

  it('throws an Error from both methods after write throws a TypeError', () => {
    const parser = createParser();
    assert.throws(() => parser.write(42), TypeError);
    assert.throws(() => parser.write('a'), { name: 'Error', message: /failed/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /failed/ });
  });

  it('throws an Error from both methods after write throws a CsvError', () => {
    const parser = createParser();
    assert.throws(() => parser.write('"a"b'), CsvError);
    assert.throws(() => parser.write('\n'), (err) => err instanceof Error && !(err instanceof CsvError));
    assert.throws(() => parser.end(), (err) => err instanceof Error && !(err instanceof CsvError));
  });

  it('throws an Error from both methods after end throws a CsvError', () => {
    const parser = createParser();
    parser.write('"open');
    assert.throws(() => parser.end(), { name: 'CsvError', code: 'UNCLOSED_QUOTE', line: 1, column: 1 });
    assert.throws(() => parser.end(), { name: 'Error', message: /failed/ });
    assert.throws(() => parser.write('x'), { name: 'Error', message: /failed/ });
  });

  it('reports a CsvError from end with the position of an opening quote from an earlier chunk', () => {
    const parser = createParser();
    parser.write('a,b\nc,');
    parser.write('"d\ne');
    assert.throws(() => parser.end(), { name: 'CsvError', line: 2, column: 3 });
  });

  it('throws a header field count mismatch from the write that ends the record', () => {
    const parser = createParser({ header: true });
    assert.deepStrictEqual(parser.write('a,b\n1,2\n3'), [{ a: '1', b: '2' }]);
    assert.throws(() => parser.write('\n'), { name: 'CsvError', code: 'FIELD_COUNT_MISMATCH', line: 3, column: 1 });
  });
});

// Inputs chosen to put chunk boundaries on every construct the scanner tracks
// across writes: CR/LF pairs, quotes, escaped quotes, BOM, delimiters, errors.
const SAMPLES = [
  '',
  'a',
  'a,b\r\nc,d\r\n',
  'a\r\rb\n\r\n\n',
  '\r\n\r\n',
  '"a""b","c\r\nd"\r\n"",x\r',
  '"""",""""""\n',
  '﻿"a",b\r\n',
  '﻿\r\n',
  'a,"b\r\nc"\r\n',
  ',,\n,\n',
  'x "y" z,"q"\n',
  'a;b,c\n"d;e";f',
  'h1,h2\r\n1,2\r\n\r\n3,4',
  'h,h\n1,2',
  'h1,"h\r\n2",h1',
  'a,b\r\n1\r\n',
  '"a"b\r\nc',
  '"a\r\nb"\r\nc"d',
  '"unclosed\r\nfield',
  'a,"b"\r\n"c""',
  '😀,"😀"x',
];

const OPTION_SETS = [
  {},
  { skipEmptyLines: true },
  { header: true },
  { header: true, skipEmptyLines: true },
  { delimiter: ';' },
];

describe('createParser: chunking matches parse()', () => {
  it('for every single split point', () => {
    for (const options of OPTION_SETS) {
      for (const text of SAMPLES) {
        const expected = parseOutcome(text, options);
        for (let i = 0; i <= text.length; i++) {
          assert.deepStrictEqual(streamOutcome(splitAt(text, [i]), options), expected, `${JSON.stringify(text)} split at ${i}`);
        }
      }
    }
  });

  it('for every pair of split points', () => {
    for (const options of OPTION_SETS) {
      for (const text of SAMPLES) {
        const expected = parseOutcome(text, options);
        for (let i = 0; i <= text.length; i++) {
          for (let j = i; j <= text.length; j++) {
            const chunks = splitAt(text, [i, j]);
            assert.deepStrictEqual(streamOutcome(chunks, options), expected, JSON.stringify(chunks));
          }
        }
      }
    }
  });

  it('for one code unit per chunk', () => {
    for (const options of OPTION_SETS) {
      for (const text of SAMPLES) {
        assert.deepStrictEqual(streamOutcome(text.split(''), options), parseOutcome(text, options), JSON.stringify(text));
      }
    }
  });

  it('for random chunkings of random inputs', () => {
    const rand = random(0xc5f);
    const alphabet = ['a', 'b', ',', ';', '"', '""', '\r', '\n', '\r\n', ' ', '﻿', 'é'];
    for (let round = 0; round < 1500; round++) {
      const length = Math.floor(rand() * 24);
      const pieces = [];
      for (let k = 0; k < length; k++) pieces.push(alphabet[Math.floor(rand() * alphabet.length)]);
      const text = (rand() < 0.2 ? '﻿' : '') + pieces.join('');
      const options = OPTION_SETS[round % OPTION_SETS.length];
      const chunks = randomChunks(text, rand);
      assert.deepStrictEqual(streamOutcome(chunks, options), parseOutcome(text, options), `seed round ${round}: ${JSON.stringify(chunks)}`);
    }
  });
});

describe('createParser: scaling', () => {
  // A parser that re-read earlier input on each write would be quadratic here:
  // about 10^11 steps, far past the time limit.
  it('parses 400k one-character chunks in linear time', { timeout: 20000 }, () => {
    const row = 'alpha,"be""ta",gamma\r\n';
    const text = row.repeat(Math.ceil(400000 / row.length));
    const parser = createParser();
    let count = 0;
    for (let i = 0; i < text.length; i++) count += parser.write(text[i]).length;
    count += parser.end().length;
    assert.equal(count, text.length / row.length);
  });

  it('builds one large quoted field from many chunks', { timeout: 20000 }, () => {
    const parser = createParser();
    parser.write('"');
    for (let i = 0; i < 200000; i++) parser.write('x""');
    const [record] = parser.write('"\n');
    assert.equal(record[0].length, 400000);
    assert.equal(record[0].slice(0, 4), 'x"x"');
  });
});

