'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { inspect } = require('node:util');
const { stringify } = require('../src/csv');

describe('stringify: records and line endings', () => {
  it('joins fields with commas and records with CRLF, ending with CRLF', () => {
    assert.equal(stringify([['a', 'b'], ['c', 'd']]), 'a,b\r\nc,d\r\n');
  });

  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
  });

  it('uses LF when eol is "\\n"', () => {
    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  });

  it('accepts an explicit CRLF eol', () => {
    assert.equal(stringify([['a']], { eol: '\r\n' }), 'a\r\n');
  });

  for (const eol of ['\r', '', 'x', '\n\r', '\r\n\r\n', 1, null]) {
    it(`rejects eol ${inspect(eol)} with a TypeError`, () => {
      assert.throws(() => stringify([['a']], { eol }), { name: 'TypeError', message: /eol must be/ });
    });
  }

  it('writes a record with one empty field as ""', () => {
    assert.equal(stringify([['a'], [''], ['b']]), 'a\r\n""\r\nb\r\n');
  });

  it('writes a record with one null or undefined field as ""', () => {
    assert.equal(stringify([[null], [undefined]]), '""\r\n""\r\n');
  });

  it('does not quote empty fields in records with more than one field', () => {
    assert.equal(stringify([['', ''], ['', 'a', '']]), ',\r\n,a,\r\n');
  });

  it('writes a record with no fields as an empty line', () => {
    assert.equal(stringify([[], ['a']]), '\r\na\r\n');
  });

  it('writes holes in sparse arrays as empty fields', () => {
    // eslint-disable-next-line no-sparse-arrays
    assert.equal(stringify([[, 'a', ,]]), ',a,\r\n');
  });
});

describe('stringify: values', () => {
  it('writes numbers and booleans with String()', () => {
    assert.equal(stringify([[1, 2.5, -0, NaN, Infinity, true, false]]), '1,2.5,0,NaN,Infinity,true,false\r\n');
  });

  it('writes null and undefined as empty fields', () => {
    assert.equal(stringify([['a', null, undefined, 'b']]), 'a,,,b\r\n');
  });

  const invalid = [
    ['a plain object', {}],
    ['an array', ['a']],
    ['a symbol', Symbol('s')],
    ['a bigint', 1n],
    ['a function', () => 'a'],
    ['a boxed string', new String('a')],
    ['a Date', new Date(0)],
  ];
  for (const [name, value] of invalid) {
    it(`rejects ${name} with a TypeError naming the row and field`, () => {
      assert.throws(() => stringify([['ok'], ['ok', value]]), { name: 'TypeError', message: /row 1, field 1/ });
    });
  }
});

describe('stringify: quoting', () => {
  const table = [
    ['the delimiter', 'a,b', '"a,b"'],
    ['a quote, doubling it', 'say "hi"', '"say ""hi"""'],
    ['a lone quote', '"', '""""'],
    ['CR', 'a\rb', '"a\rb"'],
    ['LF', 'a\nb', '"a\nb"'],
    ['CRLF', 'a\r\nb', '"a\r\nb"'],
    ['a leading space', ' a', '" a"'],
    ['a trailing space', 'a ', '"a "'],
    ['a single space', ' ', '" "'],
  ];
  for (const [name, value, expected] of table) {
    it(`quotes a field containing ${name}`, () => {
      assert.equal(stringify([[value, 'x']]), `${expected},x\r\n`);
    });
  }

  const plain = ['a b', '\ta\t', 'é', '😀', "it's", 'a;b'];
  for (const value of plain) {
    it(`does not quote ${inspect(value)}`, () => {
      assert.equal(stringify([[value, 'x']]), `${value},x\r\n`);
    });
  }

  it('quotes a number whose text contains the delimiter', () => {
    assert.equal(stringify([[1.5]], { delimiter: '.' }), '"1.5"\r\n');
  });
});

describe('stringify: delimiter option', () => {
  it('joins fields with the delimiter and quotes fields containing it', () => {
    assert.equal(stringify([['a,b', 'c;d']], { delimiter: ';' }), 'a,b;"c;d"\r\n');
  });

  it('handles regex metacharacters and backslash as delimiters', () => {
    assert.equal(stringify([['a]b', 'c']], { delimiter: ']' }), '"a]b"]c\r\n');
    assert.equal(stringify([['a\\b', 'c']], { delimiter: '\\' }), '"a\\b"\\c\r\n');
    assert.equal(stringify([['a^b', 'c-d']], { delimiter: '^' }), '"a^b"^c-d\r\n');
  });

  it('quotes fields containing a space delimiter', () => {
    assert.equal(stringify([['a b', 'c']], { delimiter: ' ' }), '"a b" c\r\n');
  });

  for (const delimiter of ['', ',,', '"', '\r', '\n', 0, null]) {
    it(`rejects delimiter ${inspect(delimiter)} with a TypeError`, () => {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError);
    });
  }
});

describe('stringify: byte order mark at the start of the output', () => {
  it('quotes a first field that starts with a BOM', () => {
    assert.equal(stringify([['\uFEFFa', 'b']]), '"\uFEFFa",b\r\n');
  });

  it('leaves a BOM unquoted anywhere else', () => {
    assert.equal(stringify([['a', '\uFEFFb'], ['\uFEFFc']]), 'a,\uFEFFb\r\n\uFEFFc\r\n');
  });

  it('quotes an empty first field when the delimiter is a BOM', () => {
    assert.equal(stringify([['', 'a']], { delimiter: '\uFEFF' }), '""\uFEFFa\r\n');
  });

  it('quotes a header name that starts with a BOM', () => {
    assert.equal(stringify([], { header: ['\uFEFFid'] }), '"\uFEFFid"\r\n');
  });
});

describe('stringify: header option', () => {
  const header = ['id', 'name'];

  it('writes the header row and then object values in header order', () => {
    const rows = [{ name: 'ann', id: 1 }, { id: 2, name: 'bo' }];
    assert.equal(stringify(rows, { header }), 'id,name\r\n1,ann\r\n2,bo\r\n');
  });

  it('writes missing and undefined keys as empty fields and ignores extra keys', () => {
    const rows = [{ id: 1 }, { name: 'x', extra: 'ignored' }, { id: undefined, name: null }];
    assert.equal(stringify(rows, { header }), 'id,name\r\n1,\r\n,x\r\n,\r\n');
  });

  it('ignores inherited properties', () => {
    const row = Object.create({ id: 'inherited' });
    row.name = 'own';
    assert.equal(stringify([row], { header }), 'id,name\r\n,own\r\n');
  });

  it('does not read Object.prototype members for columns named after them', () => {
    assert.equal(stringify([{}], { header: ['toString', 'constructor'] }), 'toString,constructor\r\n,\r\n');
  });

  it('accepts objects without a prototype', () => {
    const row = Object.assign(Object.create(null), { id: 7, name: 'n' });
    assert.equal(stringify([row], { header }), 'id,name\r\n7,n\r\n');
  });

  it('writes array rows positionally alongside object rows', () => {
    assert.equal(stringify([['1', 'a'], { id: 2, name: 'b' }], { header }), 'id,name\r\n1,a\r\n2,b\r\n');
  });

  it('writes just the header row when there are no rows', () => {
    assert.equal(stringify([], { header }), 'id,name\r\n');
  });

  it('quotes header names that need it', () => {
    assert.equal(stringify([], { header: ['a,b', ' c'] }), '"a,b"," c"\r\n');
  });

  it('writes a single empty-string column name as ""', () => {
    assert.equal(stringify([{ '': 'v' }], { header: [''] }), '""\r\nv\r\n');
  });

  it('writes a missing value in a one-column header as ""', () => {
    assert.equal(stringify([{}], { header: ['a'] }), 'a\r\n""\r\n');
  });

  it('treats header: false as no header', () => {
    assert.equal(stringify([['a']], { header: false }), 'a\r\n');
  });

  it('rejects invalid values inside object rows', () => {
    assert.throws(() => stringify([{ id: {} }], { header }), { name: 'TypeError', message: /row 0, field 0/ });
  });

  const invalidHeaders = [
    ['true', true],
    ['a string', 'id'],
    ['an empty array', []],
    ['a non-string name', ['id', 1]],
    ['a duplicate name', ['id', 'id']],
  ];
  for (const [name, value] of invalidHeaders) {
    it(`rejects ${name} as header with a TypeError`, () => {
      assert.throws(() => stringify([], { header: value }), TypeError);
    });
  }
});

describe('stringify: argument validation', () => {
  for (const rows of [undefined, null, 'a,b', 1, { 0: ['a'] }]) {
    it(`rejects rows ${inspect(rows)} with a TypeError`, () => {
      assert.throws(() => stringify(rows), { name: 'TypeError', message: /rows must be an array/ });
    });
  }

  it('rejects a row that is not an array', () => {
    assert.throws(() => stringify([['a'], 'b']), { name: 'TypeError', message: /Row 1 must be an array/ });
  });

  it('rejects object rows without a header', () => {
    assert.throws(() => stringify([{ a: 1 }]), { name: 'TypeError', message: /Row 0 must be an array/ });
  });

  it('rejects null rows with a header', () => {
    assert.throws(() => stringify([null], { header: ['a'] }), { name: 'TypeError', message: /array or an object/ });
  });

  for (const options of [null, 'x', []]) {
    it(`rejects options ${inspect(options)} with a TypeError`, () => {
      assert.throws(() => stringify([['a']], options), TypeError);
    });
  }

  it('ignores options it does not use, such as skipEmptyLines', () => {
    assert.equal(stringify([['a']], { skipEmptyLines: true }), 'a\r\n');
  });

  it('does not modify the rows, records or header it is given', () => {
    const header = ['a', 'b'];
    const rows = [['x"', ' y'], { a: 'p', b: null }];
    const snapshot = structuredClone({ header, rows });
    stringify(rows, { header });
    assert.deepStrictEqual({ header, rows }, snapshot);
  });
});

