    // eslint-disable-next-line no-sparse-arrays
    assert.equal(stringify([[, 'a', ,]]), ',a,\r\n');
  });
});

describe('stringify: values', () => {
  it('writes numbers and booleans with String()', () => {
    assert.equal(stringify([[1, 2.5, -0, NaN, Infinity, true, false]]), '1,2.5,0,NaN,Infinity,true,false\r\n');
  });

  it('writes null and undefined as empty fields', () => {
    assert.equal(stringify([['a', null, undefined, 'b']]), 'a,,,b\r\n');
  });

  const invalid = [
    ['a plain object', {}],
    ['an array', ['a']],
    ['a symbol', Symbol('s')],
    ['a bigint', 1n],
    ['a function', () => 'a'],
    ['a boxed string', new String('a')],
    ['a Date', new Date(0)],
  ];
  for (const [name, value] of invalid) {
    it(`rejects ${name} with a TypeError naming the row and field`, () => {
      assert.throws(() => stringify([['ok'], ['ok', value]]), { name: 'TypeError', message: /row 1, field 1/ });
    });
  }
});

describe('stringify: quoting', () => {
  const table = [
    ['the delimiter', 'a,b', '"a,b"'],
    ['a quote, doubling it', 'say "hi"', '"say ""hi"""'],
    ['a lone quote', '"', '""""'],
    ['CR', 'a\rb', '"a\rb"'],
    ['LF', 'a\nb', '"a\nb"'],
    ['CRLF', 'a\r\nb', '"a\r\nb"'],
    ['a leading space', ' a', '" a"'],
    ['a trailing space', 'a ', '"a "'],
    ['a single space', ' ', '" "'],
