'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, stringify } = require('../src/csv');
const { random, streamOutcome, randomChunks } = require('./helpers');

// Pieces that stress quoting: every delimiter under test, quotes, each line
// break, edge spaces, a BOM, and multi-unit characters.
const PIECES = ['a', 'Z', ' ', ',', ';', '\t', '|', 'x', '"', '""', '\r', '\n', '\r\n', '﻿', 'é', '😀', ''];
const DELIMITERS = [',', ';', '\t', '|', ' ', 'x', '﻿'];
const EOLS = ['\r\n', '\n'];

function randomField(rand) {
  if (rand() < 0.25) return '';
  const pieces = [];
  const length = 1 + Math.floor(rand() * 6);
  for (let i = 0; i < length; i++) pieces.push(PIECES[Math.floor(rand() * PIECES.length)]);
  return pieces.join('');
}

function randomRows(rand) {
  const rows = [];
  const count = Math.floor(rand() * 5);
  for (let r = 0; r < count; r++) {
    const width = 1 + Math.floor(rand() * 4);
    const row = [];
    for (let f = 0; f < width; f++) row.push(randomField(rand));
    rows.push(row);
  }
  return rows;
}

describe('round trip: parse(stringify(rows, opts), opts)', () => {
  it('returns the same rows for random string rows under every option combination', () => {
    const rand = random(20260930);
    for (let round = 0; round < 3000; round++) {
      const rows = randomRows(rand);
      const opts = {
        delimiter: DELIMITERS[round % DELIMITERS.length],
        eol: EOLS[Math.floor(round / DELIMITERS.length) % EOLS.length],
        skipEmptyLines: round % 3 === 0,
      };
      const text = stringify(rows, opts);
      assert.deepStrictEqual(parse(text, opts), rows, `round ${round}: ${JSON.stringify({ rows, opts, text })}`);
    }
  });

  const edgeRows = [
    ['a record whose only field is empty', [['']]],
    ['empty records between others', [['a'], [''], [''], ['b']]],
    ['fields made only of quotes', [['"', '""'], ['"""']]],
    ['fields made only of line breaks', [['\r'], ['\n'], ['\r\n'], ['\n\r']]],
    ['a leading BOM in the first field', [['﻿'], ['﻿a', 'b']]],
    ['fields with edge spaces', [[' '], [' a', 'b '], ['  ']]],
    ['empty fields around content', [['', ''], ['', 'a', '']]],
  ];
  for (const [name, rows] of edgeRows) {
    for (const skipEmptyLines of [false, true]) {
      it(`survives ${name} (skipEmptyLines: ${skipEmptyLines})`, () => {
        const opts = { skipEmptyLines };
        assert.deepStrictEqual(parse(stringify(rows, opts), opts), rows);
      });
    }
  }

  it('survives an empty first field with a BOM delimiter', () => {
    const opts = { delimiter: '﻿' };
    const rows = [['', 'a'], ['', '']];
    assert.deepStrictEqual(parse(stringify(rows, opts), opts), rows);
  });

  it('returns [] for no rows', () => {
    assert.deepStrictEqual(parse(stringify([])), []);
  });
});

describe('round trip: header mode', () => {
  it('reads objects written with a header back as the same objects', () => {
    const header = ['id', 'note', '__proto__', ' spaced '];
    const rows = [
      { id: '1', note: 'plain', __proto__: 'p', ' spaced ': 's' },
      { id: '2', note: 'multi\r\nline, "quoted"', ' spaced ': '' },
    ];
    // Object literals treat __proto__ as the prototype, so build the expected values explicitly.
    rows[0] = Object.defineProperty({ id: '1', note: 'plain' }, '__proto__', {
      value: 'p',
      enumerable: true,
      writable: true,
      configurable: true,
    });
    rows[0][' spaced '] = 's';
    const text = stringify(rows, { header });
    const parsed = parse(text, { header: true });
    assert.equal(parsed.length, 2);
    assert.deepStrictEqual({ ...parsed[0] }, { ...rows[0] });
    assert.deepStrictEqual(parsed[1], { id: '2', note: 'multi\r\nline, "quoted"', __proto__: Object.prototype, ' spaced ': '' });
    assert.equal(Object.getOwnPropertyDescriptor(parsed[1], '__proto__').value, '');
  });

  it('reads a one-column table with empty values back with skipEmptyLines', () => {
    const rows = [{ a: '' }, { a: 'x' }, {}];
    const text = stringify(rows, { header: ['a'] });
    assert.deepStrictEqual(parse(text, { header: true, skipEmptyLines: true }), [{ a: '' }, { a: 'x' }, { a: '' }]);
  });

  it('writes the header of an empty table so it parses back to []', () => {
    assert.deepStrictEqual(parse(stringify([], { header: ['a', 'b'] }), { header: true }), []);
  });
});

describe('round trip: through the streaming parser', () => {
  it('reads stringify output in random chunks back as the same rows', () => {
    const rand = random(7);
    for (let round = 0; round < 1000; round++) {
      const rows = randomRows(rand);
      const opts = { delimiter: DELIMITERS[round % DELIMITERS.length], eol: EOLS[round % 2], skipEmptyLines: round % 2 === 1 };
      const chunks = randomChunks(stringify(rows, opts), rand, 7);
      assert.deepStrictEqual(streamOutcome(chunks, opts), { records: rows }, `round ${round}: ${JSON.stringify(chunks)}`);
    }
