'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv');

/** Asserts parse(input) throws a CsvError with this code and position. */
function throwsAt(input, options, code, line, column) {
  assert.throws(
    () => parse(input, options),
    (err) => {
      assert.ok(err instanceof CsvError, `expected CsvError, got ${err}`);
      assert.deepStrictEqual({ code: err.code, line: err.line, column: err.column }, { code, line, column });
      assert.ok(err.message.endsWith(`at line ${line}, column ${column}`), err.message);
      return true;
    },
  );
}

function errorCases(code, table) {
