const { describe, stringifyOptions } = require('./options');

const BOM = 0xfeff;

/** Matches text that must be quoted: the delimiter, `"`, CR, LF, or a leading or trailing space. */
function quoteTest(delimiter) {
  const code = delimiter.charCodeAt(0).toString(16).padStart(4, '0');
  return new RegExp(`[\\u${code}"\\r\\n]|^ | $`);
}

function toText(value, row, field) {
  switch (typeof value) {
    case 'string':
      return value;
    case 'number':
    case 'boolean':
      return String(value);
    case 'undefined':
      return '';
    default:
      if (value === null) return '';
      throw new TypeError(
        `Value at row ${row}, field ${field} must be a string, number, boolean, null or undefined, received ${describe(value)}`,
      );
  }
}

function recordValues(row, index, header) {
  if (Array.isArray(row)) return row;
  if (header !== null && row !== null && typeof row === 'object') {
    // Own keys only, so a column named like an Object.prototype member is not
    // filled from the prototype.
    return header.map((name) => (Object.hasOwn(row, name) ? row[name] : undefined));
  }
  const expected = header === null ? 'an array' : 'an array or an object';
  throw new TypeError(`Row ${index} must be ${expected}, received ${describe(row)}`);
}

function formatRecord(values, row, delimiter, needsQuotes, isFirst) {
  const fields = new Array(values.length);
  for (let i = 0; i < values.length; i++) {
    const text = toText(values[i], row, i);
    fields[i] = needsQuotes.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
  }
  // An empty line would read back as an empty record or be skipped.
  if (fields.length === 1 && fields[0] === '') return '""';
  const line = fields.join(delimiter);
  if (isFirst && line.charCodeAt(0) === BOM) {
    // parse() drops a leading BOM, so quote the first field to keep it. The
    // field is either unquoted text starting with a BOM or empty with a BOM
    // delimiter; wrapping it in quotes is correct in both cases.
    return `"${fields[0]}"${line.slice(fields[0].length)}`;
  }
  return line;
}

