  throw new TypeError(`Row ${index} must be ${expected}, received ${describe(row)}`);
}

function formatRecord(values, row, delimiter, needsQuotes, isFirst) {
  const fields = new Array(values.length);
  for (let i = 0; i < values.length; i++) {
    const text = toText(values[i], row, i);
    fields[i] = needsQuotes.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
  }
