  if (fields.length === 1 && fields[0] === '') return '""';
  const line = fields.join(delimiter);
  if (isFirst && line.charCodeAt(0) === BOM) {
    // parse() drops a leading BOM, so quote the first field to keep it. The
    // field is either unquoted text starting with a BOM or empty with a BOM
    // delimiter; wrapping it in quotes is correct in both cases.
    return `"${fields[0]}"${line.slice(fields[0].length)}`;
  }
  return line;
}

/**
 * Serializes records to CSV text.
 *
 * @param {Array<Array<unknown> | Record<string, unknown>>} rows
 * @param {{delimiter?: string, eol?: '\r\n' | '\n', header?: string[]}} [options]
 *   With `header`, the header row is written first and rows may be objects,
 *   whose own properties are written in header order.
 * @returns {string} the records joined by `eol`, with a trailing `eol`, or ''
 *   when there is nothing to write
 * @throws {TypeError} for invalid options, rows or values
 */
function stringify(rows, options = {}) {
  const { delimiter, eol, header } = stringifyOptions(options);
  if (!Array.isArray(rows)) {
    throw new TypeError(`rows must be an array, received ${describe(rows)}`);
  }
  const needsQuotes = quoteTest(delimiter);
  const lines = [];
  if (header !== null) lines.push(formatRecord(header, 'header', delimiter, needsQuotes, true));
  for (let i = 0; i < rows.length; i++) {
    const values = recordValues(rows[i], i, header);
    lines.push(formatRecord(values, i, delimiter, needsQuotes, lines.length === 0));
  }
  return lines.length === 0 ? '' : lines.join(eol) + eol;
