'use strict';

/**
 * Error thrown for malformed CSV input.
 *
 * `line` and `column` are 1-based. Lines are counted by CRLF, LF and CR,
 * including those inside quoted fields. Columns count UTF-16 code units, and a
 * leading byte order mark does not occupy a column.
 */
class CsvError extends Error {
  /**
   * @param {string} message
   * @param {number} line
   * @param {number} column
   * @param {string} [code] UNCLOSED_QUOTE, INVALID_CLOSING_QUOTE,
   *   DUPLICATE_HEADER or FIELD_COUNT_MISMATCH when thrown by the parser.
   */
  constructor(message, line, column, code) {
    super(message);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
    this.code = code;
  }
}

const UNCLOSED_QUOTE = 'UNCLOSED_QUOTE';
const INVALID_CLOSING_QUOTE = 'INVALID_CLOSING_QUOTE';
const DUPLICATE_HEADER = 'DUPLICATE_HEADER';
const FIELD_COUNT_MISMATCH = 'FIELD_COUNT_MISMATCH';

/** Builds a CsvError whose message ends with the position it reports. */
function csvError(code, description, line, column) {
  return new CsvError(`${description} at line ${line}, column ${column}`, line, column, code);
}

module.exports = {
  CsvError,
  csvError,
  UNCLOSED_QUOTE,
  INVALID_CLOSING_QUOTE,
  DUPLICATE_HEADER,
  FIELD_COUNT_MISMATCH,
};

