const { parse, createParser, stringify } = require("./src/csv");
const rows = [];
for (let i = 0; i < 300000; i++) rows.push([String(i), "name " + i, "say \"hi\", ok", "multi\nline", ""]);
let t = process.hrtime.bigint();
const text = stringify(rows);
const ms = () => Number(process.hrtime.bigint() - t) / 1e6;
console.log("stringify", (text.length / 1e6).toFixed(1) + "M chars", ms().toFixed(0) + "ms");
t = process.hrtime.bigint();
const back = parse(text);
console.log("parse", back.length, "records", ms().toFixed(0) + "ms");
t = process.hrtime.bigint();
const p = createParser(); let n = 0;
for (let i = 0; i < text.length; i += 4096) n += p.write(text.slice(i, i + 4096)).length;
n += p.end().length;
console.log("stream 4KiB chunks", n, "records", ms().toFixed(0) + "ms");
console.log("roundtrip equal:", JSON.stringify(back) === JSON.stringify(rows));
'

